def transform(grid):
    """Complete long dotted horizontal/vertical strokes with color 2."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    row_marks = {r: [c for c, v in enumerate(grid[r]) if v != bg]
                 for r in range(h)}
    col_marks = {c: [r for r in range(h) if grid[r][c] != bg]
                 for c in range(w)}
    active_rows = {r for r, xs in row_marks.items() if len(xs) >= 3}
    active_cols = {c for c, ys in col_marks.items() if len(ys) >= 3}

    # Active rows bridge their marked span and reach an active vertical stroke
    # immediately outside either end, when one exists.
    for r in active_rows:
        xs = row_marks[r]
        lo, hi = min(xs), max(xs)
        left = [c for c in active_cols if c < lo]
        right = [c for c in active_cols if c > hi]
        if left:
            lo = max(left)
        if right:
            hi = min(right)
        for c in range(lo, hi + 1):
            if grid[r][c] == bg:
                out[r][c] = 2

    # Likewise, active columns bridge their marked span and connect to active
    # horizontal strokes immediately above or below it.
    for c in active_cols:
        ys = col_marks[c]
        lo, hi = min(ys), max(ys)
        above = [r for r in active_rows if r < lo]
        below = [r for r in active_rows if r > hi]
        if above:
            lo = max(above)
        if below:
            hi = min(below)
        for r in range(lo, hi + 1):
            if grid[r][c] == bg:
                out[r][c] = 2
    return out
